try {
	let requestSpec = me.GetRequestSpecification({
		RequestDisplayName: RequestDisplayName /* STRING */
	});

	// fyi date time parameters need to be passed in as YYYY-MM-DDTHH:mm:ss.SSSZ
	// tag names are delimited by ;
	let requestWithParameters = me.GetRequestSpecificationWithParameters({
		ParameterValue1: encodeURIComponent(Parameter1) /* STRING */ ,
		ParameterValue2: encodeURIComponent(Parameter2) /* STRING */ ,
		ParameterValue3: encodeURIComponent(Parameter3) /* STRING */ ,
		ParameterValue4: encodeURIComponent(Parameter4) /* STRING */ ,
		ParameterValue5: encodeURIComponent(Parameter5) /* STRING */ ,
		ParameterValue6: encodeURIComponent(Parameter6) /* STRING */ ,
		RequestSpecification: requestSpec.RequestSpecification /* STRING */
	});

	const configuration = me.GetConfigurationTable({
		tableName: "ServerConfiguration"
	});
	if (!configuration.ServerURL || !configuration.Username || !configuration.Password) {
		throw "ServerConfiguration must contain ServerURL, Username, and Password";
	}
	let body;
	if (RequestBody) {
		body = JSON.parse(RequestBody);
	}
	if (requestWithParameters && configuration) {
		const serverURL = configuration.ServerURL;
		const username = configuration.Username;
		const password = configuration.Password;
		const url = serverURL + requestWithParameters;
		//logger.error("{} - ExecuteRequest URL is {}", me.name, url);

		const token = me.GetOAuthToken();

		const headers = {
			"Authorization": "Bearer " + token,
			"Accept": "application/json"
		};

		const params = {
			headers: headers /* JSON */ ,
			ignoreSSLErrors: true,
			url: url,
			content: body, /* JSON */
			password: password,
			username: username
		};

		let content;
		if (requestSpec.RequestType === "GET") {
			content = Resources["ContentLoaderFunctions"].GetJSON(params);
		} else if (requestSpec.RequestType === "PUT") {
			content = Resources["ContentLoaderFunctions"].PutJSON(params);
		} else if (requestSpec.RequestType === "POST") {
			content = Resources["ContentLoaderFunctions"].PostJSON(params);
		} else {
			throw "Request type " + requestSpec.RequestType + " is not supported, ignoring request";
		}

		if (content.error) {
			logger.error("{} - ExecuteRequest content.error: {}", me.name, content.error);
		}

		if (content) {
            result = content;
		}
	}

} catch (err) {
	logger.error("{} - {}:{} - {}", me.name, err.fileName, err.lineNumber, err);
	throw ("An error has occurred. Please check the script logs for more details.");
}


