try {
	const ACCESS_TOKEN = me.oauthAccessToken;
	const EXPIRES_AT = me.oauthExpiresAt;
	const NOW = new Date();

	// Add a safety buffer (ex: 30 seconds)
	const BUFFER_MS = 30000;

	// Check if token is still valid
	if (ACCESS_TOKEN && EXPIRES_AT && (NOW.getTime() < (EXPIRES_AT.getTime() - BUFFER_MS))) {
		result = ACCESS_TOKEN;
	} else {
		const configuration = me.GetConfigurationTable({
			tableName: "ServerConfiguration"
		});
		if (!configuration.TokenURL || !configuration.Username || !configuration.Password) {
			throw "ServerConfiguration must contain TokenURL, Username, and Password";
		}

		// Request new token
		const body = "grant_type=password" +
			"&username=" + encodeURIComponent(configuration.Username) +
			"&password=" + encodeURIComponent(configuration.Password);

		const headers = {
			"Content-Type": "application/x-www-form-urlencoded",
			"Authorization": "Basic " + base64EncodeString("historian_public_rest_api:publicapisecret"),
			"Accept": "application/json"
		};

		const responseRaw = Resources["ContentLoaderFunctions"].PostText({
			url: configuration.TokenURL,
			method: "POST",
			headers: headers,
			content: body,
			ignoreSSLErrors: true
		});

		const parsed = JSON.parse(responseRaw.substring(0, responseRaw.indexOf("}") + 1));

		if (!parsed || !parsed.access_token) {
			throw "Failed to retrieve token. responseRaw = " + responseRaw;
		}

		// Store new token + expiration
		me.oauthAccessToken = parsed.access_token;
		result = me.oauthAccessToken;

		// expires_in is seconds → convert to ms
		const expiresInMs = (parsed.expires_in || 3600) * 1000;
		me.oauthExpiresAt = new Date(NOW.getTime() + expiresInMs);
	}
} catch (err) {
	logger.error("{} - {}:{} - {}", me.name, err.fileName, err.lineNumber, err);
	throw ("An error has occurred. Please check the script logs for more details.");
}


let result = DataShapes["TWSC.ProficyHistorianAPI.RequestParameters_DS"].CreateValues();
try {
	let valueArray = RequestSpecification.match(/\{(.*?)\}/g);
	let newEntry = {};
	if (valueArray) {
		for (x = 0; x < valueArray.length; x++) {
			let value = valueArray[x];
			value = value.replace(/[{}]/g, "");
			let parameterNameField = "Parameter" + (parseInt(x) + 1) + "Name";
			newEntry[parameterNameField] = value;
		}
		result.AddRow(newEntry);
	}
} catch (err) {
	logger.error("{} - {}:{} - {}", me.name, err.fileName, err.lineNumber, err);
	throw ("An error has occurred. Please check the script logs for more details.");
}


