let result = "";
try {
	let valueArray = RequestSpecification.match(/\{(.*?)\}/g);
    if (valueArray) {
        for (x = 0; x < valueArray.length; x++) {
            let value = valueArray[x];
            if (x === 0 && ParameterValue1) {
                RequestSpecification = RequestSpecification.replace(value, ParameterValue1);
            } else if (x === 1 && ParameterValue2){
                RequestSpecification = RequestSpecification.replace(value, ParameterValue2);
            } else if (x === 2 && ParameterValue3){
                RequestSpecification = RequestSpecification.replace(value, ParameterValue3);
            } else if (x === 3 && ParameterValue4){
                RequestSpecification = RequestSpecification.replace(value, ParameterValue4);
            } else if (x === 4 && ParameterValue5){
                RequestSpecification = RequestSpecification.replace(value, ParameterValue5);
            } else if (x === 5 && ParameterValue6){
                RequestSpecification = RequestSpecification.replace(value, ParameterValue6);
            }
        }
    }
    result = RequestSpecification;
} catch (err) {
	logger.error("{} - {}:{} - {}", me.name, err.fileName, err.lineNumber, err);
	throw ("An error has occurred. Please check the script logs for more details.");
}


const THING_DELIMITER = ">";
try {
	// Create an empty Infotable
	var params = {
		infoTableName: "DynamicInfoTable" // Optional: Assign a name to the infotable
	};
	var result = Resources["InfoTableFunctions"].CreateInfoTable(params);
	// Add the timestamp
	result.AddField({name: "timestamp", baseType: "DATETIME"});

	// Add the other fields
	let tagList = "";
	propertyNames.rows.toArray().forEach(row => {
		let propertyName = row.name;
		result.AddField({name: propertyName, baseType: "NUMBER"});
		tagList += thingName + THING_DELIMITER + propertyName + ";";
	});
	tagList = tagList.slice(0, -1); // remove last semicolon

	let minimum = Math.min(5000, maxItems).toString();
	let tagsJSON = me.ExecuteRequest({
		Parameter2: startDate.toISOString(),
		Parameter1: tagList,
		Parameter4: minimum,
		Parameter3: endDate.toISOString(),
		Parameter6: undefined,
		RequestDisplayName: "Get raw data",
		Parameter5: "1",
		RequestBody: undefined
	});
    tagsJSON = JSON.parse(tagsJSON);
	// logger.error(tagList +" "+ startDate.toISOString()+" "+ endDate.toISOString()+" "+minumum);
	// logger.error(JSON.stringify(tagsJSON));	
	tagsJSON.Data.forEach(data => {
		let propertyName = data.TagName.split('>')[1].trim();
		const dataItem = data;
		dataItem.Samples.forEach(sample => {
			let dt = parseDateISO(sample.TimeStamp);
			if (dt >= startDate && dt <= endDate) {
				var newRow = {};
				newRow.timestamp = parseDateISO(sample.TimeStamp);
				newRow[propertyName] = sample.Value;
				result.AddRow(newRow);
			}
		});
	});
} catch (err) {
	logger.error("{} - {}:{} - {}", me.name, err.fileName, err.lineNumber, err);
	throw ("An error has occurred. Please check the script logs for more details.");
}


